    ('botola-pro-reference', 'Botola Pro Reference', 'https://www.transfermarkt.com', 'https://www.transfermarkt.com/botola-pro-inwi/startseite/wettbewerb/MAR1', 'Reference seed for 16 current clubs; verify before production import.', '{"workbook_references":[{"sport":"Soccer","league_name":"Botola Pro","league_id":"soccer-mar-botola-pro","scope":"Botola Pro current teams / structure","checked_date":"2026-08-19","notes":"Reference seed for 16 current clubs; verify before production import."}]}'),
    ('premier-soccer-league-south-africa', 'Premier Soccer League South Africa', 'https://www.psl.co.za', 'https://www.psl.co.za/', 'Reference seed for 16 current clubs; verify before production import.', '{"workbook_references":[{"sport":"Soccer","league_name":"South African Premiership","league_id":"soccer-zaf-premiership","scope":"South African Premiership current teams / structure","checked_date":"2026-08-19","notes":"Reference seed for 16 current clubs; verify before production import."}]}'),
